from collections import Counter


def transform(grid):
    """Extend matching diagonal rays outward from a filled 2x2 seed."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Each tuple is the outward direction and the corresponding 2x2 corner.
    corners = [
        (-1, -1, 0, 0),  # upper-left -> northwest
        (-1, 1, 0, 1),   # upper-right -> northeast
        (1, -1, 1, 0),   # lower-left -> southwest
        (1, 1, 1, 1),    # lower-right -> southeast
    ]

    for r in range(h - 1):
        for c in range(w - 1):
            block = [grid[r][c], grid[r][c + 1], grid[r + 1][c], grid[r + 1][c + 1]]
            if any(value == background for value in block):
                continue

            for dr, dc, rr, cc in corners:
                color = grid[r + rr][c + cc]
                edge_r, edge_c = r + rr + dr, c + cc + dc
                if not (0 <= edge_r < h and 0 <= edge_c < w):
                    continue
                if grid[edge_r][edge_c] != color:
                    continue

                row, col = edge_r + dr, edge_c + dc
                while 0 <= row < h and 0 <= col < w:
                    if out[row][col] == background:
                        out[row][col] = color
                    row += dr
                    col += dc

    return out

def transform(grid):
    """Extend each diagonal pair of equal foreground cells in both directions."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w) or grid[r2][c2] != color:
                    continue
                for row, col, sr, sc in ((r - dr, c - dc, -dr, -dc),
                                         (r2 + dr, c2 + dc, dr, dc)):
                    while 0 <= row < h and 0 <= col < w and grid[row][col] == background:
                        out[row][col] = color
                        row += sr
                        col += sc
    return out

